    } else if b < 0xE0 {
        2
    } else if b < 0xF0 {
        3
    } else {
        4
    }
}

fn line_anchor_start(config: &Config) -> hir::Look {
    if config.crlf {
        hir::Look::StartCRLF
    } else {
        hir::Look::StartLF
    }
